import React from "react";
import { createRoot } from "react-dom/client";
import Navbar from "./Navbar"; 
import Image from "./ImageCard";
import "./style.css"
const root = createRoot(document.getElementById("d1"));

const imageData = [
  {
    imageUrl: "https://picsum.photos/id/1015/400/300",
    title: "Mountain View",
    description: "A peaceful mountain landscape.",
  },
  {
    imageUrl: "https://picsum.photos/id/1025/400/300",
    title: "Majestic Eagle",
    description: "A close shot of a soaring eagle.",
  },
  {
    imageUrl: "https://picsum.photos/id/1035/400/300",
    title: "Forest Path",
    description: "A walk through a beautiful forest.",
  },
  {
    imageUrl: "https://picsum.photos/id/1041/400/300",
    title: "Sunset Beach",
    description: "Golden sunset at a calm beach.",
  },
];

export default imageData;


root.render(
  <div>
  <Navbar></Navbar>
  <h1 className="text-3xl font-bold text-center m-9 text-green-900">Dynamic Image Gallery</h1>
  <Image></Image>
  </div>
)
